// Small, connected workflows built on the existing per-account study state.
const eventCategories={study:'Révisions',class:'Cours',exam:'Examen',sport:'Sport',personal:'Personnel'};
let calendarView='month',chapterFilter='all',historyView='today',revisionDraft=[];
const eventEditorBeforeExperience=eventEditor;
eventEditor=function(id){
 eventEditorBeforeExperience(id);
 const form=document.querySelector('#modalForm'),event=state.events.find(e=>e.id===id);
 form.querySelector('.form-actions').insertAdjacentHTML('beforebegin',`<div class="field"><label for="eventCategory">Catégorie</label><select id="eventCategory" name="category">${Object.entries(eventCategories).map(([key,label])=>`<option value="${key}" ${event?.category===key?'selected':''}>${label}</option>`).join('')}</select></div>`);
};
function weekDates(date){const start=new Date(date+'T12:00:00');start.setDate(start.getDate()-(start.getDay()+6)%7);return Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return localISO(d)})}
function agendaMarkup(day){const items=calendarItems(day);return `<span class="eyebrow">PROGRAMME DU JOUR</span><h2>${formatDate(new Date(day+'T12:00:00'))}</h2>${items.map(e=>`<article class="agenda-row"><span class="event-category ${e.kind==='task'?'task':e.category||'study'}">${e.kind==='task'?'Tâche':eventCategories[e.category]||'Événement'}</span><strong>${esc(e.title)}</strong><small>${esc(e.time||'Toute la journée')}${e.end?' – '+esc(e.end):''}${e.done?' · Terminée':''}</small><div class="agenda-actions">${e.kind==='task'?`<button class="secondary-btn" data-task-edit="${esc(e.id)}">Modifier</button>${!e.done?`<button class="link-btn" data-task-focus="${esc(e.id)}">Se concentrer</button>`:''}`:`<button class="secondary-btn" data-edit-event="${esc(e.id)}">Modifier</button><button class="icon-btn" data-remove-event="${esc(e.id)}" aria-label="Supprimer ${esc(e.title)}">${uiIcon('close')}</button>`}</div></article>`).join('')||'<div class="agenda-empty">'+uiIcon('calendar')+'<h3>Une journée à organiser</h3><p>Ajoute un cours, une révision, du sport ou un rendez-vous.</p></div>'}<button class="primary-btn" data-new-event>+ Ajouter un événement</button><button class="secondary-btn" data-calendar-task>+ Ajouter une tâche ce jour</button>`}
const calendarBeforeExperience=renderCalendar;
renderCalendar=function(){
 calendarBeforeExperience();const page=document.querySelector('#page');
 page.querySelector('.day-agenda').innerHTML=agendaMarkup(selectedDay);
 page.querySelector('.section-head').insertAdjacentHTML('afterend',`<div class="experience-toolbar"><div class="view-tabs compact-tabs" role="group" aria-label="Affichage du calendrier"><button data-calendar-view="month" class="${calendarView==='month'?'active':''}" aria-pressed="${calendarView==='month'}">Mois</button><button data-calendar-view="week" class="${calendarView==='week'?'active':''}" aria-pressed="${calendarView==='week'}">Semaine</button></div><label class="date-jump">Aller au <input type="date" id="calendarJump" value="${selectedDay}" aria-label="Aller à une date"></label></div>`);
 if(calendarView==='week'){
  const dates=weekDates(selectedDay);
  page.querySelector('.month-card').innerHTML=`<div class="month-toolbar"><h2>${formatShort(dates[0])} – ${formatShort(dates[6])}</h2><div><button class="secondary-btn" data-week="today">Aujourd’hui</button><button class="calendar-nav-btn" data-week="-1" aria-label="Semaine précédente">${uiIcon('left')}</button><button class="calendar-nav-btn" data-week="1" aria-label="Semaine suivante">${uiIcon('right')}</button></div></div><div class="week-list">${dates.map(day=>{const items=calendarItems(day);return `<button class="week-day ${selectedDay===day?'selected':''}" data-day="${day}" aria-pressed="${selectedDay===day}"><span class="week-date"><small>${new Intl.DateTimeFormat('fr-FR',{weekday:'short'}).format(new Date(day+'T12:00:00'))}</small><strong>${Number(day.slice(-2))}</strong>${day===todayISO()?'<em>Aujourd’hui</em>':''}</span><span class="week-items">${items.length?items.map(e=>`<span class="week-item ${e.done?'completed':''}"><span>${esc(e.time||'Sans heure')}</span><strong>${esc(e.title)}</strong><small>${e.kind==='task'?'Tâche':eventCategories[e.category]||'Événement'}</small></span>`).join(''):'<span class="week-free">Rien de prévu · Planifier cette journée</span>'}</span></button>`}).join('')}</div>`;
 }else{
  page.querySelectorAll('.day-cell').forEach(cell=>{const items=calendarItems(cell.dataset.day);cell.querySelectorAll('.calendar-chip').forEach((chip,i)=>{chip.classList.add(items[i].category||'study');if(items[i].done)chip.classList.add('completed')})});
 }
};
function prepareFocus(task){
 if(focusRun.running||focusRun.left<focusRun.duration){navigate('focus');showToast('Une session est déjà en cours. Termine-la avant de changer d’objectif.');return}
 const duration=Math.min(180,Math.max(1,Number(task.minutes)||25));
 Object.assign(state.focusSettings,{work:duration,subject:task.subject||'',objective:task.title});
 Object.assign(focusRun,{mode:'work',duration:duration*60,left:duration*60,subject:task.subject||'',objective:task.title,segments:{},taskId:task.id});persistFocus();navigate('focus');showToast('Session prête. Démarre quand tu veux.');
}
const subjectsBeforeExperience=renderSubjects;
renderSubjects=function(){
 subjectsBeforeExperience();const page=document.querySelector('#page');if(!learningSubjectId)return;
 const subject=state.subjects.find(s=>s.id===learningSubjectId);
 page.querySelector('.chapter-stack').insertAdjacentHTML('beforebegin',`<div class="experience-toolbar chapter-toolbar"><label class="experience-search">${uiIcon('search')}<input type="search" id="chapterQuery" placeholder="Rechercher un chapitre" aria-label="Rechercher dans cette matière"></label><select id="chapterFilter" aria-label="Filtrer les chapitres"><option value="all">Tous les chapitres</option><option value="open" ${chapterFilter==='open'?'selected':''}>À travailler</option><option value="done" ${chapterFilter==='done'?'selected':''}>Maîtrisés</option></select><span id="chapterCount" role="status"></span></div><p class="helper chapter-help">Valide les quatre étapes pour débloquer « Terminer ». Tes notes restent enregistrées dans chaque chapitre.</p>`);
 page.querySelectorAll('[data-chapter-card]').forEach(card=>{const c=subject.chapters.find(c=>c.id===card.dataset.chapterCard);card.querySelector('.chapter-notes summary').textContent=c.notes||c.resource?'Notes & ressource · enregistrées':'Notes & ressource';card.querySelector('.chapter-card-head').insertAdjacentHTML('beforeend',`<button class="chapter-focus link-btn" data-chapter-focus="${esc(c.id)}">${uiIcon('focus')} Réviser</button>`)});
 filterChapters();
};
function filterChapters(){const query=(document.querySelector('#chapterQuery')?.value||'').toLocaleLowerCase('fr');let count=0;const subject=state.subjects.find(s=>s.id===learningSubjectId);document.querySelectorAll('[data-chapter-card]').forEach(card=>{const c=subject.chapters.find(c=>c.id===card.dataset.chapterCard);card.hidden=!c.name.toLocaleLowerCase('fr').includes(query)||(chapterFilter==='done'&&!c.done)||(chapterFilter==='open'&&c.done);if(!card.hidden)count++});const output=document.querySelector('#chapterCount');if(output)output.textContent=`${count} chapitre${count!==1?'s':''}`;let empty=document.querySelector('#chapterNoResults');if(!empty){document.querySelector('.chapter-stack').insertAdjacentHTML('beforeend','<p id="chapterNoResults" class="agenda-empty" hidden>Aucun chapitre dans cette vue. Essaie un autre nom ou filtre.</p>');empty=document.querySelector('#chapterNoResults')}empty.hidden=count>0||!subject.chapters.length}
const focusBeforeExperience=renderFocus;
renderFocus=function(){
 focusBeforeExperience();const history=document.querySelector('.session-history');if(!history||history.hidden)return;
 const since=weekDates(todayISO())[0],sessions=state.focusSessions.filter(s=>historyView==='all'||(historyView==='week'?s.date>=since:s.date===todayISO())).slice().reverse();
 history.innerHTML=`<div class="section-title-row"><div><span class="eyebrow">TON TRAVAIL ENREGISTRÉ</span><h2>Historique des sessions</h2></div><select id="historyView" aria-label="Période de l’historique">${[['today','Aujourd’hui'],['week','Cette semaine'],['all','Tout l’historique']].map(([v,l])=>`<option value="${v}" ${historyView===v?'selected':''}>${l}</option>`).join('')}</select></div><p class="helper">${sessions.length} session${sessions.length!==1?'s':''} · ${studyHours(sessions.reduce((n,s)=>n+Number(s.minutes)*60,0))}</p>${sessions.slice(0,50).map(s=>`<div class="session-row"><div><strong>${esc(s.subject||'Étude libre')}</strong><small>${formatShort(s.date)} · ${esc(s.objective||'Session enregistrée')}</small></div><strong>${studyHours(Number(s.minutes)*60)}</strong></div>`).join('')||'<div class="agenda-empty"><p>Aucune session sur cette période. Ton temps sera enregistré quand tu termineras une session.</p></div>'}${sessions.length>50?'<p class="helper">Les 50 sessions les plus récentes sont affichées.</p>':''}`;
};
const progressBeforeExperience=renderProgress;
renderProgress=function(){progressBeforeExperience();document.querySelectorAll('.mastery-progress-row').forEach((row,i)=>{const s=state.subjects[i];if(s)row.insertAdjacentHTML('beforeend',`<button class="link-btn" data-progress-subject="${esc(s.id)}">Voir les chapitres ${uiIcon('right')}</button>`)});document.querySelectorAll('.activity-bar>span').forEach(bar=>{bar.tabIndex=0;bar.setAttribute('aria-label',bar.title);bar.dataset.label=bar.title})};
// Deterministic planner: suggested tasks are reviewed before any are saved.
function makeRevisionPlan(subjects,tasks,{start,days,daily,session}){
 const candidates=subjects.flatMap(s=>s.chapters.filter(c=>!c.done).map(c=>({subject:s.name,chapter:c.id,subjectId:s.id,title:`${LEARNING_STEPS.find(step=>!c.steps?.[step.key])?.label||'Valider le chapitre'} · ${c.name}`,units:chapterUnits(c)}))).sort((a,b)=>a.units-b.units||a.subject.localeCompare(b.subject,'fr'));
 const plan=[];let cursor=0;
 for(let day=0;day<days;day++){
  const d=new Date(start+'T12:00:00');d.setDate(d.getDate()+day);const date=localISO(d);
  let remaining=Math.max(0,daily-tasks.filter(t=>!t.done&&t.date===date).reduce((n,t)=>n+(Number(t.minutes)||0),0));
  while(remaining>=session&&cursor<candidates.length){const candidate=candidates[cursor++];if(tasks.some(t=>!t.done&&t.revisionChapter===candidate.chapter))continue;plan.push({...candidate,date,minutes:session});remaining-=session}
 }
 return plan;
}
renderAI=function(){
 document.querySelector('#page').innerHTML=header('Plan de révision','Transforme les chapitres à travailler en tâches concrètes.')+`<section class="planner-intro"><span class="planner-icon">${uiIcon('calendar')}</span><div><h2>Une semaine qui tient dans ton agenda.</h2><p>Les chapitres les moins avancés passent en premier. Le temps de tes tâches déjà prévues est déduit du budget quotidien.</p></div></section><div class="planner-layout"><section class="activity-panel"><h2>Ton rythme</h2><form id="revisionForm">${field('Commencer le','start','date',`value="${todayISO()}"`)}<div class="settings-grid">${field('Nombre de jours','days','number','min="1" max="14" value="7"')}${field('Budget quotidien (min)','daily','number','min="15" max="480" step="5" value="60"')}</div><div class="field"><label for="revisionSession">Durée d’une tâche</label><select id="revisionSession" name="session"><option value="25">25 min</option><option value="30" selected>30 min</option><option value="45">45 min</option><option value="60">60 min</option></select></div><button class="primary-btn" type="submit">Préparer mon plan</button></form><p class="helper">Planification selon ta progression, sans IA. Les recommandations AI+ restent en préparation.</p></section><section class="activity-panel" id="revisionResults" aria-live="polite"><div class="agenda-empty">${uiIcon('subjects')}<h2>Prévisualise avant d’ajouter</h2><p>Choisis ton rythme pour voir les tâches proposées. Tu pourras retirer celles qui ne te conviennent pas.</p><button class="link-btn" data-go="subjects">Gérer mes chapitres</button></div></section></div>`;
 document.querySelector('#revisionForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(Number(data.daily)<Number(data.session)){showToast('Le budget quotidien doit couvrir au moins une tâche.');return}revisionDraft=makeRevisionPlan(state.subjects,state.tasks,{start:data.start,days:Number(data.days),daily:Number(data.daily),session:Number(data.session)});renderRevisionDraft()};
};
function renderRevisionDraft(){const target=document.querySelector('#revisionResults');target.innerHTML=`<div class="section-title-row"><h2>Ton plan proposé</h2><span>${revisionDraft.length} tâches</span></div>${revisionDraft.length?`<p class="helper">${revisionDraft.reduce((n,t)=>n+t.minutes,0)} minutes de révision · les créneaux horaires restent libres.</p><div class="revision-list">${revisionDraft.map((t,i)=>`<div class="revision-row"><div><span>${formatShort(t.date)} · ${t.minutes} min · ${esc(t.subject)}</span><strong>${esc(t.title)}</strong></div><button class="icon-btn" data-revision-remove="${i}" aria-label="Retirer ${esc(t.title)}">${uiIcon('close')}</button></div>`).join('')}</div><button class="primary-btn" data-revision-save>Ajouter ${revisionDraft.length} tâches à mon agenda</button>`:'<div class="agenda-empty"><h3>Aucune nouvelle tâche à proposer</h3><p>Ajoute des chapitres à travailler ou augmente ton budget quotidien. Les chapitres déjà planifiés ne sont pas ajoutés une seconde fois.</p><button class="secondary-btn" data-go="subjects">Voir mes matières</button></div>'}`}
const accountBeforeExperience=renderAccount;
renderAccount=function(){accountBeforeExperience();document.querySelector('#page').insertAdjacentHTML('beforeend',`<section class="activity-panel account-help"><h2>Bien utiliser Prepago</h2><div class="help-grid"><details><summary>Comment est calculée ma progression ?</summary><p>Chaque chapitre comporte cinq étapes. Tes validations, tâches terminées et sessions enregistrées alimentent tes résultats.</p></details><details><summary>Où retrouver mes notes ?</summary><p>Ouvre une matière, puis « Notes & ressource » sous un chapitre. Les notes d’annales se trouvent dans chaque épreuve CNC.</p></details><details><summary>Comment organiser mes révisions ?</summary><p>Prépare un plan de révision, ajuste les tâches et lance une session de concentration depuis le menu d’une tâche.</p></details><details><summary>Comment reprendre mon chrono ?</summary><p>Tu peux changer de page pendant une session. Retrouve-la dans Concentration pour la mettre en pause ou enregistrer ton travail.</p></details></div><div class="account-resources"><a class="secondary-btn" href="/methode/" target="_blank" rel="noopener">Découvrir la méthode</a><a class="link-btn" href="/confidentialite/" target="_blank" rel="noopener">Politique de confidentialité</a><a class="link-btn" href="/conditions/" target="_blank" rel="noopener">Conditions d’utilisation</a></div></section>`)};
pageNames.ai='Plan de révision';document.querySelector('[data-page="ai"]').innerHTML='<span class="icon"></span>Plan de révision';
document.addEventListener('input',e=>{if(e.target.id==='chapterQuery')filterChapters()});
document.addEventListener('change',e=>{
 if(e.target.id==='chapterFilter'){chapterFilter=e.target.value;filterChapters()}
 if(e.target.id==='calendarJump'&&e.target.value){selectedDay=e.target.value;calendarDate=new Date(selectedDay+'T12:00:00');render()}
 if(e.target.id==='historyView'){historyView=e.target.value;render()}
});
document.addEventListener('click',e=>{
 const view=e.target.closest('[data-calendar-view]');if(view){calendarView=view.dataset.calendarView;render()}
 const week=e.target.closest('[data-week]');if(week){const d=new Date(selectedDay+'T12:00:00');if(week.dataset.week==='today')selectedDay=todayISO();else{d.setDate(d.getDate()+7*Number(week.dataset.week));selectedDay=localISO(d)}calendarDate=new Date(selectedDay+'T12:00:00');render()}
 const focus=e.target.closest('[data-task-focus]');if(focus){const t=state.tasks.find(t=>t.id===focus.dataset.taskFocus);if(t)prepareFocus(t)}
 const duplicate=e.target.closest('[data-task-duplicate]');if(duplicate){const t=state.tasks.find(t=>t.id===duplicate.dataset.taskDuplicate);if(t){state.tasks.push({...t,id:uid('t'),title:t.title+' (copie)',done:false,completedAt:null,revisionChapter:null,date:todayISO()});save();render();showToast('Copie ajoutée pour aujourd’hui')}}
 const chapter=e.target.closest('[data-chapter-focus]');if(chapter){const s=state.subjects.find(s=>s.id===learningSubjectId),c=s?.chapters.find(c=>c.id===chapter.dataset.chapterFocus);if(c)prepareFocus({subject:s.name,title:c.name,minutes:state.focusSettings.work})}
 const subject=e.target.closest('[data-progress-subject]');if(subject){currentPage='subjects';resetLearningSelection(subject.dataset.progressSubject);render();window.scrollTo(0,0)}
 const remove=e.target.closest('[data-revision-remove]');if(remove){revisionDraft.splice(Number(remove.dataset.revisionRemove),1);renderRevisionDraft()}
 if(e.target.closest('[data-revision-save]')&&revisionDraft.length){const rows=revisionDraft.filter(r=>!state.tasks.some(t=>!t.done&&t.revisionChapter===r.chapter));state.tasks.push(...rows.map(r=>({id:uid('t'),title:r.title,subject:r.subject,date:r.date,minutes:r.minutes,time:'',priority:'medium',done:false,revisionChapter:r.chapter})));revisionDraft=[];taskView='all';taskQuery=taskSubjectFilter=taskPriorityFilter='';save();navigate('tasks');showToast(`${rows.length} tâches ajoutées. Tu peux ajuster leurs dates et durées.`)}
});
window.addEventListener('prepago:state-replaced',()=>{revisionDraft=[];chapterFilter='all';historyView='today'});
// Opening a new section always starts at its heading, including from long plans.
const navigateBeforeExperience=navigate;
navigate=function(page){const changed=currentPage!==page;const result=navigateBeforeExperience(page);if(changed)window.scrollTo({top:0,behavior:'instant'});return result};
